thread_local! {
    static API: RefCell<Option<Box<dyn ChrApi>>> = const { RefCell::new(None) };
}

/// Installs the implementation (call on the Python thread before the interpreter runs scripts).
pub fn set_api(api: Box<dyn ChrApi>) {
    API.with(|a| *a.borrow_mut() = Some(api));
}

fn with_api<R>(f: impl FnOnce(&mut dyn ChrApi) -> R) -> Option<R> {
    API.with(|a| a.borrow_mut().as_mut().map(|b| f(b.as_mut())))
}

